META_ENCRYPTION = "ce_encryption"
META_KEY_WRAP = "ce_key_wrap"
META_NONCE = "ce_nonce"
META_WRAPPED_KEY = "ce_wrapped_key"
META_KEY_ID = "ce_key_id"


